public class Main {
    public static void bubbleSort(int[] arr) {
        boolean isSwapped = false;
        for(int i=0;i<arr.length-1; i++){
            isSwapped = false;
            for(int j=0;j<arr.length-1-i; j++){
                if(arr[j] >arr[j+1]){
                    int temp = arr[j+1];
                    arr[j+1] = arr[j];
                    arr[j] = temp;
                    isSwapped = true;
                }
            }

            if(!isSwapped){
                return;
            }
        }
    }

    public static void main(String[] args) {
        int[] a = {5, 2, 8, 1, 9}; bubbleSort(a);
