    public static int countPrimesIE(int n){
        if(n<2){
            return 0;
        }

        int count = 1;
        for(int i=2; i<=n; i++){
            int x = (int) (i/2) + 1;
            boolean isPrime = true;
            for(int j=x; j>1; j--){
                if(i%j == 0){
                    isPrime = false;
                    break;
                }
            }

            if(isPrime ){
                //System.out.print(i+"--");
                count++;
            }
        }
        return count;
    }

    public static int countPrimesOpt(int n) {
        if (n < 2) return 0;

        boolean[] isComposite = new boolean[n + 1];
        int count = 0;

        for (int i = 2; i <= n; i++) {
            if (!isComposite[i]) {
                count++;
                // mark multiples of i as composite, starting from i*i
                for (long j = (long) i * i; j <= n; j += i) {
                    isComposite[(int) j] = true;
                }
            }
        }
        return count;
    }

    public static int countPrimes(int n) {
        // Sieve of Eratosthenes

        return countPrimesOpt(n);
    }

    public static void main(String[] args) {
        System.out.println(countPrimes(10));  // 4
        System.out.println(countPrimes(0));  // 0
        System.out.println(countPrimes(1));  // 0
